// Seva UI installer (catalogue tabs + sankalpam booking panel). Run from the repo root or apps\web:  node install-seva-ui.mjs
// Existing files are copied to <name>.bak before being replaced. en.json / ta.json get NEW keys added; nothing is removed.
import fs from 'node:fs';
import path from 'node:path';

let root = process.argv[2] ? path.resolve(process.argv[2]) : process.cwd();
const isWeb = (d) => fs.existsSync(path.join(d, 'src', 'dictionaries', 'en.json'));
if (!isWeb(root) && isWeb(path.join(root, 'apps', 'web'))) root = path.join(root, 'apps', 'web');
if (!isWeb(root)) {
  console.error('Could not find src\\dictionaries\\en.json in ' + root + '. Run this from the repo root or from apps\\web.');
  process.exit(1);
}
if (!fs.existsSync(path.join(root, 'src', 'components', 'cart', 'CartProvider.tsx'))) {
  console.error('The seva shop is not installed yet (src\\components\\cart missing). Run install-seva-shop.mjs first.');
  process.exit(1);
}
console.log('Installing into ' + root + '\n');

const FILES = {"src/data/sankalpam.ts":"// DEFAULT LISTS for the sankalpam form. The CMS can replace these later.\n// The value that is saved is the English name; the label shown follows the visitor's language.\n// A devotee can also type a value that is not in a list (see ChoiceField).\n\nimport type { Locale } from '@/lib/i18n';\nimport type { L } from '@/data/sevas';\n\nexport type FamilyMember = { name: string; relation: string; rasi: string; nakshatram: string };\n\nexport const MAX_FAMILY = 10;\n\n// 12 rasis (Moon signs)\nexport const RASIS: L[] = [\n  { en: 'Mesham (Aries)', ta: 'மேஷம்' },\n  { en: 'Rishabam (Taurus)', ta: 'ரிஷபம்' },\n  { en: 'Mithunam (Gemini)', ta: 'மிதுனம்' },\n  { en: 'Kadagam (Cancer)', ta: 'கடகம்' },\n  { en: 'Simmam (Leo)', ta: 'சிம்மம்' },\n  { en: 'Kanni (Virgo)', ta: 'கன்னி' },\n  { en: 'Thulam (Libra)', ta: 'துலாம்' },\n  { en: 'Viruchigam (Scorpio)', ta: 'விருச்சிகம்' },\n  { en: 'Dhanusu (Sagittarius)', ta: 'தனுசு' },\n  { en: 'Makaram (Capricorn)', ta: 'மகரம்' },\n  { en: 'Kumbam (Aquarius)', ta: 'கும்பம்' },\n  { en: 'Meenam (Pisces)', ta: 'மீனம்' },\n];\n\n// 27 nakshatrams (birth stars), in the Tamil spelling order\nexport const NAKSHATRAMS: L[] = [\n  { en: 'Ashwini', ta: 'அசுவினி' },\n  { en: 'Bharani', ta: 'பரணி' },\n  { en: 'Krithigai', ta: 'கார்த்திகை' },\n  { en: 'Rohini', ta: 'ரோகிணி' },\n  { en: 'Mrigashirsham', ta: 'மிருகசீரிடம்' },\n  { en: 'Thiruvathirai', ta: 'திருவாதிரை' },\n  { en: 'Punarpoosam', ta: 'புனர்பூசம்' },\n  { en: 'Poosam', ta: 'பூசம்' },\n  { en: 'Ayilyam', ta: 'ஆயில்யம்' },\n  { en: 'Magam', ta: 'மகம்' },\n  { en: 'Pooram', ta: 'பூரம்' },\n  { en: 'Uthiram', ta: 'உத்திரம்' },\n  { en: 'Hastham', ta: 'அஸ்தம்' },\n  { en: 'Chithirai', ta: 'சித்திரை' },\n  { en: 'Swathi', ta: 'சுவாதி' },\n  { en: 'Visakam', ta: 'விசாகம்' },\n  { en: 'Anusham', ta: 'அனுஷம்' },\n  { en: 'Kettai', ta: 'கேட்டை' },\n  { en: 'Moolam', ta: 'மூலம்' },\n  { en: 'Pooradam', ta: 'பூராடம்' },\n  { en: 'Uthiradam', ta: 'உத்திராடம்' },\n  { en: 'Thiruvonam', ta: 'திருவோணம்' },\n  { en: 'Avittam', ta: 'அவிட்டம்' },\n  { en: 'Sathayam', ta: 'சதயம்' },\n  { en: 'Poorattathi', ta: 'பூரட்டாதி' },\n  { en: 'Uthirattathi', ta: 'உத்திரட்டாதி' },\n  { en: 'Revathi', ta: 'ரேவதி' },\n];\n\n// Commonly used gotrams. A starting set only: the ashram should review it,\n// and anything missing can be typed by the devotee.\nexport const GOTRAMS: L[] = [\n  { en: 'Agastya', ta: 'அகஸ்திய' },\n  { en: 'Angirasa', ta: 'ஆங்கிரஸ' },\n  { en: 'Atri', ta: 'அத்ரி' },\n  { en: 'Athreya', ta: 'ஆத்ரேய' },\n  { en: 'Bharadwaja', ta: 'பரத்வாஜ' },\n  { en: 'Garga', ta: 'கர்க' },\n  { en: 'Gautama', ta: 'கௌதம' },\n  { en: 'Harita', ta: 'ஹாரீத' },\n  { en: 'Jamadagni', ta: 'ஜமதக்னி' },\n  { en: 'Kanva', ta: 'கண்வ' },\n  { en: 'Kashyapa', ta: 'காஷ்யப' },\n  { en: 'Kaundinya', ta: 'கௌண்டின்ய' },\n  { en: 'Kaushika', ta: 'கௌசிக' },\n  { en: 'Maudgalya', ta: 'மௌத்கல்ய' },\n  { en: 'Parashara', ta: 'பராசர' },\n  { en: 'Sandilya', ta: 'சாண்டில்ய' },\n  { en: 'Srivatsa', ta: 'ஸ்ரீவத்ஸ' },\n  { en: 'Upamanyu', ta: 'உபமன்யு' },\n  { en: 'Vadhula', ta: 'வாதூல' },\n  { en: 'Vasishta', ta: 'வசிஷ்ட' },\n  { en: 'Vatsa', ta: 'வத்ஸ' },\n  { en: 'Vishwamitra', ta: 'விஸ்வாமித்ர' },\n];\n\nexport const RELATIONS: L[] = [\n  { en: 'Spouse', ta: 'வாழ்க்கைத் துணை' },\n  { en: 'Son', ta: 'மகன்' },\n  { en: 'Daughter', ta: 'மகள்' },\n  { en: 'Father', ta: 'தந்தை' },\n  { en: 'Mother', ta: 'தாய்' },\n  { en: 'Brother', ta: 'சகோதரர்' },\n  { en: 'Sister', ta: 'சகோதரி' },\n];\n\n// Label to show for a saved value: the list's name in the visitor's language, or the typed text as it is\nexport const labelFor = (list: L[], value: string, locale: Locale) => list.find((i) => i.en === value)?.[locale] ?? value;\n","src/data/sevas.ts":"// DUMMY DATA. The CMS portal will replace this file: keep the shape, swap the source.\n// Every text has an English and a Tamil version. `amount: 0` means \"as per the devotee's ability\".\n\nimport type { Locale } from '@/lib/i18n';\n\nexport type L = { en: string; ta: string };\n// 'corpus' items belong to the Corpus List tab; the others belong to the Seva List tab\nexport type SevaKind = 'festival' | 'regular' | 'annadhanam' | 'corpus';\n\nexport type Seva = {\n  slug: string;\n  kind: SevaKind;\n  name: L;\n  when: L;                 // shown on cards and on the detail page\n  amount: number;          // fixed amount in rupees; 0 = devotee chooses\n  minAmount: number;       // lowest amount a devotee may choose (only when amount is 0)\n  from?: string;           // first date the seva can be booked for (YYYY-MM-DD)\n  to?: string;             // last date (same as `from` for a one-day seva)\n  weekday?: number;        // 0 = Sunday ... 6 = Saturday: seva is offered only on this day\n  note?: L;                // extra line shown under the date\n  benefit?: L;             // one-line \"Benefits\" text on the card (dummy text from the design; the ashram must confirm)\n  status: 'open' | 'closed';\n  maxQty: number;\n  description: { en: string[]; ta: string[] }; // paragraphs; empty until the ashram writes them\n  includes: { label: L; price: number }[];     // itemised list, if any\n};\n\nconst base = { minAmount: 1, status: 'open' as const, maxQty: 10, description: { en: [], ta: [] }, includes: [] };\n\nexport const SEVAS: Seva[] = [\n  { ...base, slug: 'kasi-viswanathar-annabishekam', kind: 'festival', amount: 0, from: '2026-10-25', to: '2026-10-25',\n    name: { en: 'Sri Kasi Viswanathar Annabishekam', ta: 'ஸ்ரீ காசி விஸ்வநாதர் அன்னாபிஷேகம்' },\n    when: { en: '25 Oct 2026', ta: '25 அக் 2026' } },\n  { ...base, slug: 'skanda-shashti-puja', kind: 'festival', amount: 0, from: '2026-11-15', to: '2026-11-15',\n    name: { en: 'Sri Skanda Shashti Puja', ta: 'ஸ்ரீ ஸ்கந்த சஷ்டி பூஜை' },\n    when: { en: '15 Nov 2026', ta: '15 நவ 2026' } },\n  { ...base, slug: 'navaratri-one-day-puja-kanikai', kind: 'festival', amount: 10001, from: '2026-10-11', to: '2026-10-21',\n    name: { en: 'Sri Saradha Navaratri One Day Puja Kanikai', ta: 'ஸ்ரீ சாரதா நவராத்திரி ஒரு நாள் பூஜை காணிக்கை' },\n    when: { en: '11 – 21 Oct 2026', ta: '11 – 21 அக் 2026' } },\n  { ...base, slug: 'navaratri-sumangali-puja', kind: 'festival', amount: 2500, from: '2026-10-11', to: '2026-10-21',\n    name: { en: 'Sri Saradha Navaratri Sumangali Puja', ta: 'ஸ்ரீ சாரதா நவராத்திரி சுமங்கலி பூஜை' },\n    when: { en: '11 – 21 Oct 2026', ta: '11 – 21 அக் 2026' } },\n  { ...base, slug: 'navaratri-sankalpam', kind: 'festival', amount: 501, from: '2026-10-11', to: '2026-10-21',\n    name: { en: 'Sri Saradha Navaratri Sankalpam', ta: 'ஸ்ரீ சாரதா நவராத்திரி சங்கல்பம்' },\n    when: { en: '11 – 21 Oct 2026', ta: '11 – 21 அக் 2026' } },\n  { ...base, slug: 'navaratri-2026', kind: 'festival', amount: 0, from: '2026-10-11', to: '2026-10-21',\n    name: { en: 'Sri Saradha Navaratri 2026', ta: 'ஸ்ரீ சாரதா நவராத்திரி 2026' },\n    when: { en: '11 – 21 Oct 2026', ta: '11 – 21 அக் 2026' },\n    includes: [\n      { label: { en: 'Homa materials', ta: 'ஹோம பொருட்கள்' }, price: 20000 },\n      { label: { en: 'Ghee, 20 kg', ta: 'நெய், 20 கிலோ' }, price: 15000 },\n      { label: { en: 'Thirumangalyam (2 gram gold)', ta: 'திருமாங்கல்யம் (2 கிராம் தங்கம்)' }, price: 35000 },\n      { label: { en: 'Flowers and garlands', ta: 'பூக்களும் மாலைகளும்' }, price: 15000 },\n      { label: { en: 'Vastra samarpanam for Sri Mangala Chandi Homam', ta: 'ஸ்ரீ மங்கள சண்டி ஹோமத்துக்கு வஸ்திர சமர்ப்பணம்' }, price: 10000 },\n      { label: { en: 'Sivacharyar sambavanai and Saptasati parayana ritvik sambavanai', ta: 'சிவாச்சாரியார் சம்பாவனை மற்றும் சப்தசதி பாராயண ரித்விக் சம்பாவனை' }, price: 90000 },\n      { label: { en: 'Homa Sankalpam', ta: 'ஹோம சங்கல்பம்' }, price: 501 },\n    ] },\n  { ...base, slug: 'go-puja', benefit: { en: 'Brings prosperity, peace and purifies domestic environment.', ta: 'செழிப்பையும் அமைதியையும் தரும்; இல்லச் சூழலைத் தூய்மைப்படுத்தும்.' },\n    kind: 'regular', amount: 200,\n    name: { en: 'Go Puja', ta: 'கோபூஜை' }, when: { en: 'As desired', ta: 'விரும்பிய நாளில்' } },\n  { ...base, slug: 'archanai', benefit: { en: 'Daily offering in your name with Vedic chantings.', ta: 'வேத மந்திரங்களுடன் உங்கள் பெயரில் தினசரி அர்ப்பணிப்பு.' },\n    kind: 'regular', amount: 200,\n    name: { en: 'Archanai', ta: 'அர்ச்சனை' }, when: { en: 'As desired', ta: 'விரும்பிய நாளில்' } },\n  { ...base, slug: 'special-puja', kind: 'regular', amount: 500,\n    name: { en: 'Special Puja (birthday, wedding day, etc.)', ta: 'சிறப்பு பூஜை (பிறந்தநாள், திருமண நாள் போன்றவை)' },\n    when: { en: 'As desired', ta: 'விரும்பிய நாளில்' } },\n  { ...base, slug: 'ganga-puja', benefit: { en: 'Performed on the holy banks of river Pennai.', ta: 'புனிதமான பெண்ணை ஆற்றின் கரையில் நடத்தப்படுகிறது.' },\n    kind: 'regular', amount: 200, weekday: 5,\n    name: { en: 'Sri Ganga Puja (Aarti)', ta: 'ஸ்ரீ கங்கா பூஜை (ஆரத்தி)' },\n    when: { en: 'Every Friday', ta: 'ஒவ்வொரு வெள்ளிக்கிழமை' } },\n  { ...base, slug: 'pradosa-puja', benefit: { en: 'Special bi-monthly worship of Lord Shiva.', ta: 'சிவபெருமானுக்கான சிறப்பு மாதம் இருமுறை வழிபாடு.' },\n    kind: 'regular', amount: 200,\n    name: { en: 'Sri Pradosa Puja', ta: 'ஸ்ரீ பிரதோஷ கால பூஜை' },\n    when: { en: 'Only on Triyodasi', ta: 'திரயோதசி அன்று மட்டும்' },\n    note: { en: 'Offered only on Triyodasi. Please choose a Triyodasi date; the ashram will confirm it.', ta: 'திரயோதசி அன்று மட்டும் நடைபெறும். திரயோதசி தேதியைத் தேர்ந்தெடுக்கவும்; ஆசிரமம் உறுதிப்படுத்தும்.' } },\n  { ...base, slug: 'special-abhishekam', benefit: { en: 'Detailed ritual bath to presiding deity.', ta: 'மூலவருக்குச் செய்யப்படும் விரிவான அபிஷேகம்.' },\n    kind: 'regular', amount: 2000,\n    name: { en: 'Special Abhishekam and Alankaram', ta: 'சிறப்பு அபிஷேகம் & அலங்காரம்' },\n    when: { en: 'As desired', ta: 'விரும்பிய நாளில்' } },\n  { ...base, slug: 'udayastamana-puja', benefit: { en: 'Worship services from sunrise to sunset.', ta: 'சூரிய உதயம் முதல் அஸ்தமனம் வரையிலான வழிபாட்டுச் சேவைகள்.' },\n    kind: 'regular', amount: 5000,\n    name: { en: 'Udayastamana Puja', ta: 'உதயாஸ்தமன பூஜை' }, when: { en: 'As desired', ta: 'விரும்பிய நாளில்' } },\n  { ...base, slug: 'parivara-devata-puja', kind: 'regular', amount: 1000,\n    name: { en: 'Sri Parivara Devata Puja', ta: 'ஸ்ரீ பரிவார தேவதா பூஜை' }, when: { en: 'As desired', ta: 'விரும்பிய நாளில்' } },\n  { ...base, slug: 'annadhanam', kind: 'annadhanam', amount: 9000, weekday: 4,\n    name: { en: 'Annadhanam', ta: 'அன்னதானம்' },\n    when: { en: 'Every Thursday', ta: 'ஒவ்வொரு வியாழக்கிழமை' } },\n  // Corpus List (dummy). Names and the Rs 50,000 amount come from the old \"Annadhanam & Corpus\" page;\n  // what each corpus funds and its rules are NOT known yet and must come from the ashram.\n  { ...base, slug: 'adiguru-nitya-puja-corpus', kind: 'corpus', amount: 50000,\n    name: { en: 'Sri Adiguru Nitya Puja Corpus', ta: 'ஸ்ரீ ஆதிகுரு நித்ய பூஜை கார்பஸ்' },\n    when: { en: 'As desired', ta: 'விரும்பிய நாளில்' } },\n  { ...base, slug: 'corpus-fund-general', kind: 'corpus', amount: 0,\n    name: { en: 'Corpus Fund', ta: 'கார்பஸ் நிதி' },\n    when: { en: 'As desired', ta: 'விரும்பிய நாளில்' } },\n];\n\nexport const getSeva = (slug: string) => SEVAS.find((s) => s.slug === slug);\nexport const txt = (l: L, locale: Locale) => l[locale];\n\n// How the date for a seva is chosen\nexport type DateMode = 'fixed' | 'range' | 'weekday' | 'any';\nexport function dateMode(s: Seva): DateMode {\n  if (s.from && s.from === s.to) return 'fixed';\n  if (s.from && s.to) return 'range';\n  if (s.weekday !== undefined) return 'weekday';\n  return 'any';\n}\n","src/components/sevas/ChoiceField.tsx":"'use client';\n\nimport { useState } from 'react';\nimport type { Locale } from '@/lib/i18n';\nimport type { L } from '@/data/sevas';\n\nconst OTHER = '__other__';\n\nexport const fieldClass =\n  'w-full rounded-md border border-rose bg-rose/30 px-3 py-2.5 text-charcoal placeholder:text-charcoal/50 focus:border-saffron focus:outline-none focus-visible:ring-2 focus-visible:ring-saffron/40';\n\ntype Props = {\n  id: string;\n  label: string;\n  value: string;                 // the saved value: a list item's English name, or the typed text\n  onChange: (value: string) => void;\n  options: L[];\n  locale: Locale;\n  placeholder: string;           // first option, e.g. \"Select\"\n  otherLabel: string;            // last option, e.g. \"Other (type manually)\"\n  typeLabel: string;             // label of the text box, e.g. \"Type here\"\n  error?: string;\n};\n\n// A list to choose from, with a last option \"Other\" that opens a text box for typing a value by hand\nexport default function ChoiceField({ id, label, value, onChange, options, locale, placeholder, otherLabel, typeLabel, error }: Props) {\n  const known = options.some((o) => o.en === value);\n  const [manual, setManual] = useState(false);\n  const showManual = manual || (value !== '' && !known); // a typed value that was saved earlier opens the text box too\n  const selectValue = showManual ? OTHER : value;\n\n  return (\n    <div>\n      <label htmlFor={id} className=\"block text-sm font-bold text-charcoal\">{label}</label>\n      <select\n        id={id}\n        value={selectValue}\n        onChange={(e) => {\n          if (e.target.value === OTHER) {\n            setManual(true);\n            onChange('');\n          } else {\n            setManual(false);\n            onChange(e.target.value);\n          }\n        }}\n        aria-invalid={!!error}\n        aria-describedby={error ? `${id}-error` : undefined}\n        className={`${fieldClass} mt-1`}\n      >\n        <option value=\"\">{placeholder}</option>\n        {options.map((o) => (\n          <option key={o.en} value={o.en}>{o[locale]}</option>\n        ))}\n        <option value={OTHER}>{otherLabel}</option>\n      </select>\n\n      {showManual && (\n        <input\n          id={`${id}-other`}\n          type=\"text\"\n          value={value}\n          onChange={(e) => onChange(e.target.value)}\n          placeholder={typeLabel}\n          aria-label={`${label}: ${typeLabel}`}\n          autoComplete=\"off\"\n          className={`${fieldClass} mt-2`}\n        />\n      )}\n      {error && <p id={`${id}-error`} role=\"alert\" className=\"mt-1 text-sm font-semibold text-maroon\">{error}</p>}\n    </div>\n  );\n}\n","src/components/sevas/SankalpamWizard.tsx":"'use client';\n\nimport { useEffect, useId, useRef, useState } from 'react';\nimport Link from 'next/link';\nimport { useRouter } from 'next/navigation';\nimport type { Dictionary } from '@/lib/dictionary';\nimport type { Locale } from '@/lib/i18n';\nimport { WEEKDAYS, formatDate, rupees, todayISO, weekdayOf } from '@/lib/format';\nimport { dateMode, txt, type Seva } from '@/data/sevas';\nimport { GOTRAMS, MAX_FAMILY, NAKSHATRAMS, RASIS, RELATIONS, type FamilyMember } from '@/data/sankalpam';\nimport { useCart } from '@/components/cart/CartProvider';\nimport ChoiceField, { fieldClass } from './ChoiceField';\n\ntype T = Dictionary['sevas'];\ntype Member = FamilyMember & { uid: number };\n\nconst STORE = 'vedaneri.sankalpam.v1';\ntype Saved = { devotee: string; gotram: string; rasi: string; nakshatram: string; family: FamilyMember[] };\n\nfunction readSaved(): Saved | null {\n  try {\n    const raw = window.localStorage.getItem(STORE);\n    return raw ? (JSON.parse(raw) as Saved) : null;\n  } catch {\n    return null;\n  }\n}\nfunction writeSaved(v: Saved) {\n  try {\n    window.localStorage.setItem(STORE, JSON.stringify(v));\n  } catch {\n    /* ignore: storage can be blocked */\n  }\n}\n\n// Booking panel in three steps: 1 choose a seva, 2 sankalpam credentials, 3 date selection.\n// On the list page the seva comes from the card the visitor picked; on a detail page it is fixed.\nexport default function SankalpamWizard({\n  seva,\n  locale,\n  t,\n  fixed = false,\n  onChangeSeva,\n}: {\n  seva: Seva | null;\n  locale: Locale;\n  t: T;\n  fixed?: boolean;\n  onChangeSeva?: () => void;\n}) {\n  const router = useRouter();\n  const { add } = useCart();\n  const headingId = useId();\n  const headingRef = useRef<HTMLHeadingElement>(null);\n  const uid = useRef(0);\n  const firstRender = useRef(true);\n\n  const [step, setStep] = useState<1 | 2 | 3>(seva ? 2 : 1);\n  const [today, setToday] = useState('');\n  const [devotee, setDevotee] = useState('');\n  const [gotram, setGotram] = useState('');\n  const [rasi, setRasi] = useState('');\n  const [nakshatram, setNakshatram] = useState('');\n  const [family, setFamily] = useState<Member[]>([]);\n  const [date, setDate] = useState(seva && dateMode(seva) === 'fixed' ? seva.from ?? '' : '');\n  const [amountStr, setAmountStr] = useState('');\n  const [qty, setQty] = useState(1);\n  const [errors, setErrors] = useState<Record<string, string>>({});\n  const [added, setAdded] = useState<string | null>(null);\n\n  // After the page loads: today's date (kept out of the first render so server and browser match), and the details used last time\n  useEffect(() => {\n    setToday(todayISO());\n    const s = readSaved();\n    if (s) {\n      setDevotee(s.devotee ?? '');\n      setGotram(s.gotram ?? '');\n      setRasi(s.rasi ?? '');\n      setNakshatram(s.nakshatram ?? '');\n      setFamily((s.family ?? []).map((m) => ({ ...m, uid: ++uid.current })));\n    }\n  }, []);\n\n  // A different seva was picked: start again at step 2 with a clean date and amount\n  useEffect(() => {\n    setStep(seva ? 2 : 1);\n    setErrors({});\n    setAmountStr('');\n    setQty(1);\n    setDate(seva && dateMode(seva) === 'fixed' ? seva.from ?? '' : '');\n    if (seva) setAdded(null);\n  }, [seva]);\n\n  // Move keyboard and screen-reader focus to the panel heading when the step changes (not on first load)\n  useEffect(() => {\n    if (firstRender.current) {\n      firstRender.current = false;\n      return;\n    }\n    headingRef.current?.focus({ preventScroll: true });\n  }, [step, added, seva]);\n\n  const mode = seva ? dateMode(seva) : 'any';\n  const past = !!seva && (mode === 'fixed' || mode === 'range') && !!seva.to && !!today && seva.to < today;\n  const closed = !!seva && (seva.status !== 'open' || past);\n  const choose = !!seva && seva.amount === 0;\n  const unit = seva ? (choose ? Number(amountStr) || 0 : seva.amount) : 0;\n  const total = unit * (choose ? 1 : qty);\n  const dayName = seva && seva.weekday !== undefined ? WEEKDAYS[locale][seva.weekday] : '';\n  const minDate = mode === 'range' && seva?.from && seva.from > today ? seva.from : today;\n  const maxDate = mode === 'range' ? seva?.to : undefined;\n\n  const dateHelp = !seva\n    ? ''\n    : mode === 'fixed'\n      ? t.dateFixed.replace('{date}', formatDate(seva.from!, locale))\n      : mode === 'range'\n        ? t.dateRange.replace('{from}', formatDate(seva.from!, locale)).replace('{to}', formatDate(seva.to!, locale))\n        : mode === 'weekday'\n          ? t.dateWeekday.replaceAll('{day}', dayName)\n          : t.dateAny;\n\n  const clearError = (key: string) =>\n    setErrors((e) => {\n      if (!e[key]) return e;\n      const { [key]: _gone, ...rest } = e;\n      return rest;\n    });\n\n  const updateMember = (id: number, patch: Partial<FamilyMember>) => {\n    setFamily((f) => f.map((m) => (m.uid === id ? { ...m, ...patch } : m)));\n    if (patch.name) clearError(`m${id}`);\n  };\n\n  function goDate() {\n    const e: Record<string, string> = {};\n    if (!devotee.trim()) e.devotee = t.errName;\n    family.forEach((m) => {\n      if (!m.name.trim()) e[`m${m.uid}`] = t.errMember;\n    });\n    setErrors(e);\n    if (Object.keys(e).length === 0) setStep(3);\n  }\n\n  function validateDate() {\n    if (!seva) return false;\n    const e: Record<string, string> = {};\n    if (mode !== 'fixed') {\n      if (!date) e.date = t.errDate;\n      else if (date < today) e.date = t.errDatePast;\n      else if (mode === 'range' && (date < (seva.from as string) || date > (seva.to as string))) e.date = t.errDateRange;\n      else if (mode === 'weekday' && weekdayOf(date) !== seva.weekday) e.date = t.errDateWeekday.replace('{day}', dayName);\n    }\n    if (choose && !(Number(amountStr) >= seva.minAmount)) e.amount = t.errAmount.replace('{min}', rupees(seva.minAmount));\n    setErrors(e);\n    return Object.keys(e).length === 0;\n  }\n\n  function addToCart(goToCart: boolean) {\n    if (!seva || closed || !validateDate()) return;\n    const members: FamilyMember[] = family\n      .filter((m) => m.name.trim())\n      .map(({ name, relation, rasi: r, nakshatram: n }) => ({ name: name.trim(), relation, rasi: r, nakshatram: n }));\n    add({\n      slug: seva.slug,\n      qty: choose ? 1 : qty,\n      unit,\n      date,\n      devotee: devotee.trim(),\n      gotram,\n      nakshatram,\n      rasi,\n      family: members,\n    });\n    writeSaved({ devotee: devotee.trim(), gotram, rasi, nakshatram, family: members });\n    if (goToCart) {\n      router.push(`/${locale}/cart`);\n      return;\n    }\n    setAdded(txt(seva.name, locale));\n    onChangeSeva?.(); // on the list page this clears the picked seva so the panel returns to step 1\n  }\n\n  const stepLabels = [t.stepSeva, t.stepCredentials, t.stepDate];\n  const shownStep = added !== null ? 1 : step;\n  const title = shownStep === 1 ? t.panelTitleSeva : shownStep === 2 ? t.panelTitleCred : t.panelTitleDate;\n  const text = shownStep === 1 ? t.panelTextSeva : shownStep === 2 ? t.panelTextCred : t.panelTextDate;\n  const btnPrimary =\n    'rounded-md bg-maroon px-5 py-3 text-center font-semibold text-white transition-colors hover:bg-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron';\n  const btnGhost =\n    'rounded-md border-2 border-rose bg-white px-5 py-3 text-center font-semibold text-charcoal transition-colors hover:bg-rose focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron';\n\n  return (\n    <section aria-labelledby={headingId} className=\"rounded-2xl bg-white p-6 shadow-lg ring-1 ring-rose\">\n      <h2\n        id={headingId}\n        ref={headingRef}\n        tabIndex={-1}\n        className=\"font-display text-3xl font-semibold leading-tight text-maroon focus:outline-none [html[lang='ta']_&]:!leading-[1.35] [html[lang='ta']_&]:text-2xl\"\n      >\n        {title}\n      </h2>\n      <p className=\"mt-1 text-sm text-charcoal/70\">{text}</p>\n\n      {/* Steps */}\n      <ol aria-label={t.stepsLabel} className=\"mt-5 flex items-center gap-2\">\n        {stepLabels.map((label, i) => {\n          const n = i + 1;\n          const done = n < shownStep;\n          const on = n === shownStep;\n          return (\n            <li key={label} aria-current={on ? 'step' : undefined} className=\"flex items-center gap-2\">\n              <span\n                title={label}\n                className={`flex h-6 w-6 items-center justify-center rounded-full text-xs font-bold ${\n                  done || on ? 'bg-saffron text-charcoal' : 'bg-white text-charcoal/60 ring-1 ring-rose'\n                } ${on ? 'ring-2 ring-saffron/40 ring-offset-1' : ''}`}\n              >\n                {done ? '✓' : n}\n              </span>\n              <span className=\"sr-only\">{label}</span>\n              {i < stepLabels.length - 1 && <span aria-hidden=\"true\" className={`h-0.5 w-10 ${done ? 'bg-saffron' : 'bg-rose'}`} />}\n            </li>\n          );\n        })}\n      </ol>\n\n      {/* After adding */}\n      {added !== null && (\n        <div role=\"status\" className=\"mt-6 rounded-xl bg-saffron/15 p-5 text-center\">\n          <p className=\"font-display text-2xl font-semibold text-maroon\">✓ {t.added}</p>\n          <p className=\"mt-1 text-charcoal\">{added}</p>\n          <div className=\"mt-4 flex flex-col gap-3\">\n            <Link href={`/${locale}/cart`} className={btnPrimary}>{t.viewCart}</Link>\n            {fixed ? (\n              <Link href={`/${locale}/sevas`} className={btnGhost}>{t.keepBrowsing}</Link>\n            ) : (\n              <button type=\"button\" onClick={() => setAdded(null)} className={btnGhost}>{t.chooseAnother}</button>\n            )}\n          </div>\n        </div>\n      )}\n\n      {/* Step 1, nothing picked yet */}\n      {added === null && !seva && (\n        <p className=\"mt-6 rounded-xl bg-rose/50 p-5 text-center font-serif text-charcoal/85\">{t.panelEmpty}</p>\n      )}\n\n      {/* A seva is picked */}\n      {added === null && seva && (\n        <>\n          <div className=\"mt-5 flex items-start justify-between gap-3 rounded-lg bg-rose/50 p-3\">\n            <div className=\"min-w-0\">\n              <p className=\"font-semibold leading-snug text-charcoal\">{txt(seva.name, locale)}</p>\n              <p className=\"text-sm text-charcoal/75\">\n                {seva.amount > 0 ? rupees(seva.amount) : t.abilityLabel} · {txt(seva.when, locale)}\n              </p>\n            </div>\n            {!fixed && (\n              <button type=\"button\" onClick={onChangeSeva} className=\"shrink-0 text-sm font-semibold text-maroon underline underline-offset-4 hover:text-charcoal\">\n                {t.changeSeva}\n              </button>\n            )}\n          </div>\n\n          {closed ? (\n            <div className=\"mt-5 rounded-xl bg-rose/60 p-5 text-center\">\n              <p className=\"font-display text-2xl font-semibold text-maroon\">{past ? t.statusPast : t.statusClosed}</p>\n              <Link href={`/${locale}/sevas`} className=\"mt-4 inline-block rounded-md bg-maroon px-5 py-2.5 font-semibold text-white hover:bg-charcoal\">{t.backLabel}</Link>\n            </div>\n          ) : step === 2 ? (\n            <form\n              noValidate\n              onSubmit={(e) => {\n                e.preventDefault();\n                goDate();\n              }}\n              className=\"mt-5 space-y-4\"\n            >\n              <div>\n                <label htmlFor=\"kartha\" className=\"block text-sm font-bold text-charcoal\">{t.kartha}</label>\n                <input\n                  id=\"kartha\"\n                  value={devotee}\n                  onChange={(e) => {\n                    setDevotee(e.target.value);\n                    if (e.target.value.trim()) clearError('devotee');\n                  }}\n                  autoComplete=\"off\"\n                  aria-invalid={!!errors.devotee}\n                  aria-describedby={errors.devotee ? 'kartha-error' : 'kartha-hint'}\n                  className={`${fieldClass} mt-1`}\n                />\n                {errors.devotee ? (\n                  <p id=\"kartha-error\" role=\"alert\" className=\"mt-1 text-sm font-semibold text-maroon\">{errors.devotee}</p>\n                ) : (\n                  <p id=\"kartha-hint\" className=\"mt-1 text-sm text-charcoal/70\">{t.devoteeNameHelp}</p>\n                )}\n              </div>\n\n              <ChoiceField id=\"gotram\" label={t.gotramFull} value={gotram} onChange={setGotram} options={GOTRAMS} locale={locale}\n                placeholder={t.choose} otherLabel={t.otherOption} typeLabel={t.typeManually} />\n              <div className={`grid gap-4 ${fixed ? 'sm:grid-cols-2' : ''}`}>\n                <ChoiceField id=\"rasi\" label={t.rasiFull} value={rasi} onChange={setRasi} options={RASIS} locale={locale}\n                  placeholder={t.choose} otherLabel={t.otherOption} typeLabel={t.typeManually} />\n                <ChoiceField id=\"nakshatram\" label={t.nakshatramFull} value={nakshatram} onChange={setNakshatram} options={NAKSHATRAMS} locale={locale}\n                  placeholder={t.choose} otherLabel={t.otherOption} typeLabel={t.typeManually} />\n              </div>\n              <p className=\"text-sm text-charcoal/70\">{t.optionalNote}</p>\n\n              {/* Family members */}\n              {family.map((m, i) => (\n                <fieldset key={m.uid} className=\"rounded-xl border border-rose p-4\">\n                  <legend className=\"px-1 text-sm font-bold text-maroon\">{t.familyTitle.replace('{n}', String(i + 1))}</legend>\n                  <div className=\"space-y-3\">\n                    <div>\n                      <label htmlFor={`m${m.uid}-name`} className=\"block text-sm font-bold text-charcoal\">{t.memberName}</label>\n                      <input\n                        id={`m${m.uid}-name`}\n                        value={m.name}\n                        onChange={(e) => updateMember(m.uid, { name: e.target.value })}\n                        autoComplete=\"off\"\n                        aria-invalid={!!errors[`m${m.uid}`]}\n                        aria-describedby={errors[`m${m.uid}`] ? `m${m.uid}-error` : undefined}\n                        className={`${fieldClass} mt-1`}\n                      />\n                      {errors[`m${m.uid}`] && <p id={`m${m.uid}-error`} role=\"alert\" className=\"mt-1 text-sm font-semibold text-maroon\">{errors[`m${m.uid}`]}</p>}\n                    </div>\n                    <ChoiceField id={`m${m.uid}-relation`} label={t.relation} value={m.relation} onChange={(v) => updateMember(m.uid, { relation: v })} options={RELATIONS} locale={locale}\n                      placeholder={t.choose} otherLabel={t.otherOption} typeLabel={t.typeManually} />\n                    <div className={`grid gap-3 ${fixed ? 'sm:grid-cols-2' : ''}`}>\n                      <ChoiceField id={`m${m.uid}-rasi`} label={t.rasiFull} value={m.rasi} onChange={(v) => updateMember(m.uid, { rasi: v })} options={RASIS} locale={locale}\n                        placeholder={t.choose} otherLabel={t.otherOption} typeLabel={t.typeManually} />\n                      <ChoiceField id={`m${m.uid}-nakshatram`} label={t.nakshatramFull} value={m.nakshatram} onChange={(v) => updateMember(m.uid, { nakshatram: v })} options={NAKSHATRAMS} locale={locale}\n                        placeholder={t.choose} otherLabel={t.otherOption} typeLabel={t.typeManually} />\n                    </div>\n                    <button type=\"button\" onClick={() => setFamily((f) => f.filter((x) => x.uid !== m.uid))} className=\"text-sm font-semibold text-maroon underline underline-offset-4 hover:text-charcoal\">\n                      {t.removeMember}\n                    </button>\n                  </div>\n                </fieldset>\n              ))}\n\n              {family.length < MAX_FAMILY ? (\n                <button\n                  type=\"button\"\n                  onClick={() => setFamily((f) => [...f, { uid: ++uid.current, name: '', relation: '', rasi: '', nakshatram: '' }])}\n                  className=\"inline-flex items-center gap-2 text-sm font-bold text-maroon hover:text-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\"\n                >\n                  <span aria-hidden=\"true\" className=\"flex h-5 w-5 items-center justify-center rounded-full border-2 border-maroon text-sm leading-none\">+</span>\n                  {t.addFamily}\n                </button>\n              ) : (\n                <p className=\"text-sm text-charcoal/70\">{t.maxFamily.replace('{n}', String(MAX_FAMILY))}</p>\n              )}\n              {family.length > 0 && <p className=\"text-sm text-charcoal/70\">{t.familyHelp}</p>}\n\n              <div className={`grid gap-3 pt-2 ${fixed ? '' : 'sm:grid-cols-2'}`}>\n                {!fixed && (\n                  <button type=\"button\" onClick={onChangeSeva} className={btnGhost}>{t.back}</button>\n                )}\n                <button type=\"submit\" className={btnPrimary}>{t.nextDate}</button>\n              </div>\n            </form>\n          ) : (\n            <form\n              noValidate\n              onSubmit={(e) => {\n                e.preventDefault();\n                addToCart(false);\n              }}\n              className=\"mt-5 space-y-4\"\n            >\n              <div>\n                <label htmlFor=\"seva-date\" className=\"block text-sm font-bold text-charcoal\">{t.dateLabel}</label>\n                {mode === 'fixed' ? (\n                  <p id=\"seva-date\" className=\"mt-1 rounded-md bg-rose/50 px-4 py-2.5 font-semibold text-charcoal\">{formatDate(seva.from!, locale)}</p>\n                ) : (\n                  <input\n                    id=\"seva-date\"\n                    type=\"date\"\n                    value={date}\n                    min={minDate || undefined}\n                    max={maxDate}\n                    onChange={(e) => {\n                      setDate(e.target.value);\n                      clearError('date');\n                    }}\n                    aria-invalid={!!errors.date}\n                    aria-describedby={errors.date ? 'seva-date-error' : 'seva-date-hint'}\n                    className={`${fieldClass} mt-1`}\n                  />\n                )}\n                {errors.date ? (\n                  <p id=\"seva-date-error\" role=\"alert\" className=\"mt-1 text-sm font-semibold text-maroon\">{errors.date}</p>\n                ) : (\n                  <p id=\"seva-date-hint\" className=\"mt-1 text-sm text-charcoal/70\">{dateHelp}</p>\n                )}\n              </div>\n              {seva.note && <p className=\"rounded-md bg-saffron/15 px-4 py-2 text-sm font-semibold text-charcoal\">{txt(seva.note, locale)}</p>}\n\n              {choose ? (\n                <div>\n                  <label htmlFor=\"amount\" className=\"block text-sm font-bold text-charcoal\">{t.amountInput}</label>\n                  <div className=\"relative mt-1\">\n                    <span aria-hidden=\"true\" className=\"absolute left-4 top-1/2 -translate-y-1/2 font-bold text-charcoal/70\">₹</span>\n                    <input\n                      id=\"amount\"\n                      inputMode=\"numeric\"\n                      value={amountStr}\n                      onChange={(e) => setAmountStr(e.target.value.replace(/\\D/g, ''))}\n                      aria-invalid={!!errors.amount}\n                      aria-describedby={errors.amount ? 'amount-error' : 'amount-hint'}\n                      className={`${fieldClass} pl-9`}\n                    />\n                  </div>\n                  {errors.amount ? (\n                    <p id=\"amount-error\" role=\"alert\" className=\"mt-1 text-sm font-semibold text-maroon\">{errors.amount}</p>\n                  ) : (\n                    <p id=\"amount-hint\" className=\"mt-1 text-sm text-charcoal/70\">{t.amountHelp}</p>\n                  )}\n                </div>\n              ) : (\n                <div>\n                  <p className=\"text-sm font-bold text-charcoal\">{t.qtyLabel}</p>\n                  <div className=\"mt-1 inline-flex items-center rounded-md border-2 border-rose\">\n                    <button type=\"button\" aria-label={t.decrease} disabled={qty <= 1} onClick={() => setQty((q) => Math.max(1, q - 1))} className=\"h-11 w-11 text-xl font-bold text-maroon hover:bg-rose disabled:opacity-40\">−</button>\n                    <span aria-live=\"polite\" className=\"w-12 text-center text-lg font-bold\">{qty}</span>\n                    <button type=\"button\" aria-label={t.increase} disabled={qty >= seva.maxQty} onClick={() => setQty((q) => Math.min(seva.maxQty, q + 1))} className=\"h-11 w-11 text-xl font-bold text-maroon hover:bg-rose disabled:opacity-40\">+</button>\n                  </div>\n                </div>\n              )}\n\n              <p className=\"flex items-baseline justify-between border-t border-rose pt-4\">\n                <span className=\"font-semibold text-charcoal/80\">{t.totalLabel}</span>\n                <span className=\"font-display text-3xl font-semibold text-maroon\">{rupees(total)}</span>\n              </p>\n\n              <div className=\"grid gap-3\">\n                <button type=\"submit\" className={btnPrimary}>{t.addToSevaCart}</button>\n                <button type=\"button\" onClick={() => addToCart(true)} className={btnGhost}>{t.addAndGo}</button>\n                <button type=\"button\" onClick={() => setStep(2)} className=\"text-sm font-semibold text-maroon underline underline-offset-4 hover:text-charcoal\">{t.back}</button>\n              </div>\n            </form>\n          )}\n        </>\n      )}\n    </section>\n  );\n}\n","src/components/sevas/SevaOfferCard.tsx":"'use client';\n\nimport Link from 'next/link';\nimport type { Dictionary } from '@/lib/dictionary';\nimport type { Locale } from '@/lib/i18n';\nimport { rupees } from '@/lib/format';\nimport { txt, type Seva } from '@/data/sevas';\n\nfunction Calendar() {\n  return (\n    <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\" aria-hidden=\"true\" className=\"shrink-0\">\n      <rect x=\"3\" y=\"5\" width=\"18\" height=\"16\" rx=\"2\" />\n      <path d=\"M3 10h18M8 3v4M16 3v4\" />\n    </svg>\n  );\n}\n\n// One offering in the catalogue: name, amount, benefit, and the button that starts the booking panel\nexport default function SevaOfferCard({\n  seva,\n  locale,\n  t,\n  selected,\n  closed,\n  past,\n  onSelect,\n}: {\n  seva: Seva;\n  locale: Locale;\n  t: Dictionary['sevas'];\n  selected: boolean;\n  closed: boolean;\n  past: boolean;\n  onSelect: () => void;\n}) {\n  const name = txt(seva.name, locale);\n  return (\n    <article className={`flex h-full flex-col rounded-xl bg-white p-5 shadow-sm transition-shadow ${selected ? 'ring-2 ring-saffron shadow-md' : 'ring-1 ring-rose hover:shadow-md'}`}>\n      <div className=\"flex items-start justify-between gap-3\">\n        <h3 className=\"font-display text-xl font-semibold leading-tight text-maroon [html[lang='ta']_&]:!leading-[1.4] [html[lang='ta']_&]:text-lg\">\n          <Link href={`/${locale}/sevas/${seva.slug}`} className=\"underline-offset-4 hover:underline focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\">\n            {name}\n          </Link>\n        </h3>\n        <p className=\"shrink-0 text-right font-display text-xl font-semibold leading-tight text-saffron [html[lang='ta']_&]:text-base\">\n          {seva.amount > 0 ? rupees(seva.amount) : t.abilityShort}\n        </p>\n      </div>\n\n      {seva.benefit && (\n        <p className=\"mt-3 text-sm leading-relaxed text-charcoal/85\">\n          <span className=\"font-semibold\">{t.benefitsLabel}</span> {txt(seva.benefit, locale)}\n        </p>\n      )}\n      <p className=\"mt-2 flex items-center gap-2 text-sm text-charcoal/70\">\n        <Calendar />\n        {txt(seva.when, locale)}\n      </p>\n\n      <div className=\"mt-auto pt-4\">\n        <button\n          type=\"button\"\n          disabled={closed}\n          aria-pressed={selected}\n          onClick={onSelect}\n          className={`w-full rounded-md border px-4 py-2.5 text-sm font-bold transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron ${\n            closed\n              ? 'cursor-not-allowed border-rose bg-rose/60 text-charcoal/60'\n              : selected\n                ? 'border-saffron bg-saffron text-charcoal'\n                : 'border-saffron bg-white text-maroon hover:bg-saffron/15'\n          }`}\n        >\n          {closed ? (past ? t.pastLabel : t.closedLabel) : selected ? `✓ ${t.selected}` : t.addToSevaCart}\n        </button>\n      </div>\n    </article>\n  );\n}\n","src/components/sevas/SevaCard.tsx":"import Link from 'next/link';\nimport type { Dictionary } from '@/lib/dictionary';\nimport type { Locale } from '@/lib/i18n';\nimport { rupees, sevaPhoto } from '@/lib/format';\nimport { txt, type Seva } from '@/data/sevas';\n\nfunction Calendar() {\n  return (\n    <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\" aria-hidden=\"true\" className=\"shrink-0\">\n      <rect x=\"3\" y=\"5\" width=\"18\" height=\"16\" rx=\"2\" />\n      <path d=\"M3 10h18M8 3v4M16 3v4\" />\n    </svg>\n  );\n}\n\n// One seva in the list. The whole card opens the detail page.\nexport default function SevaCard({ seva, locale, t }: { seva: Seva; locale: Locale; t: Dictionary['sevas'] }) {\n  const name = txt(seva.name, locale);\n  const kindLabel = seva.kind === 'corpus' ? t.tabCorpus : t.filters.find((f) => f.key === seva.kind)?.label ?? '';\n  const closed = seva.status !== 'open';\n  return (\n    <article className=\"group relative flex h-full flex-col overflow-hidden rounded-2xl bg-white shadow-md ring-2 ring-rose transition-shadow focus-within:ring-saffron hover:shadow-xl\">\n      <div className=\"relative h-40 overflow-hidden bg-maroon\">\n        <div className=\"absolute inset-0 bg-cover bg-center transition-transform duration-500 group-hover:scale-105\" style={{ backgroundImage: sevaPhoto(seva.slug) }} role=\"img\" aria-label={name} />\n        <span className=\"absolute left-3 top-3 rounded-full bg-white/95 px-3 py-1 text-xs font-bold text-maroon shadow\">{kindLabel}</span>\n      </div>\n\n      <div className=\"flex flex-1 flex-col p-5\">\n        <h3 className=\"font-display text-2xl font-semibold leading-tight text-maroon [html[lang='ta']_&]:!leading-[1.4] [html[lang='ta']_&]:text-xl\">\n          <Link href={`/${locale}/sevas/${seva.slug}`} className=\"after:absolute after:inset-0 focus-visible:outline-none\">\n            {name}\n          </Link>\n        </h3>\n        <p className=\"mt-3 flex items-center gap-2 text-sm font-semibold text-charcoal/80\">\n          <Calendar />\n          {txt(seva.when, locale)}\n        </p>\n        <p className=\"mt-4 font-display text-4xl font-semibold leading-none text-charcoal\">\n          {seva.amount > 0 ? rupees(seva.amount) : <span className=\"text-2xl text-saffron [html[lang='ta']_&]:text-xl\">{t.abilityLabel}</span>}\n        </p>\n        <p className=\"mt-auto pt-5\">\n          <span className={`inline-flex w-full items-center justify-center rounded-md px-5 py-3 text-center font-semibold transition-colors ${closed ? 'bg-rose text-charcoal/70' : 'bg-maroon text-white group-hover:bg-charcoal'}`}>\n            {closed ? t.closedLabel : t.viewLabel}\n          </span>\n        </p>\n      </div>\n    </article>\n  );\n}\n","src/components/SevaList.tsx":"'use client';\n\nimport { useEffect, useMemo, useRef, useState } from 'react';\nimport type { Dictionary } from '@/lib/dictionary';\nimport type { Locale } from '@/lib/i18n';\nimport { todayISO } from '@/lib/format';\nimport { SEVAS, txt, type Seva } from '@/data/sevas';\nimport SevaOfferCard from './sevas/SevaOfferCard';\nimport SankalpamWizard from './sevas/SankalpamWizard';\n\ntype T = Dictionary['sevas'];\ntype Tab = 'all' | 'seva' | 'corpus';\n\n// The seva catalogue: tabs (All / Seva List / Corpus List), search and sort, the offering cards,\n// and the booking panel on the right that opens when a card is picked.\nexport default function SevaList({ t, locale }: { t: T; locale: Locale }) {\n  const [tab, setTab] = useState<Tab>('all');\n  const [kind, setKind] = useState('all');\n  const [query, setQuery] = useState('');\n  const [sort, setSort] = useState('default');\n  const [selected, setSelected] = useState<Seva | null>(null);\n  const [today, setToday] = useState('');\n  const panelRef = useRef<HTMLDivElement>(null);\n\n  useEffect(() => setToday(todayISO()), []);\n\n  const counts: Record<Tab, number> = {\n    all: SEVAS.length,\n    seva: SEVAS.filter((s) => s.kind !== 'corpus').length,\n    corpus: SEVAS.filter((s) => s.kind === 'corpus').length,\n  };\n\n  const shown = useMemo(() => {\n    const q = query.trim().toLowerCase();\n    const list = SEVAS.filter(\n      (s) =>\n        (tab === 'all' || (tab === 'corpus' ? s.kind === 'corpus' : s.kind !== 'corpus')) &&\n        (tab === 'corpus' || kind === 'all' || s.kind === kind) &&\n        (!q || txt(s.name, locale).toLowerCase().includes(q)),\n    );\n    if (sort === 'low') return [...list].sort((a, b) => (a.amount || Infinity) - (b.amount || Infinity));\n    if (sort === 'high') return [...list].sort((a, b) => b.amount - a.amount);\n    return list;\n  }, [tab, kind, query, sort, locale]);\n\n  const isPast = (s: Seva) => !!today && !!s.to && s.to < today;\n  const isClosed = (s: Seva) => s.status !== 'open' || isPast(s);\n\n  function pick(s: Seva) {\n    setSelected(s);\n    // On a phone the panel sits below the cards, so bring it into view\n    if (typeof window !== 'undefined' && !window.matchMedia('(min-width: 1024px)').matches) {\n      panelRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });\n    }\n  }\n\n  const reset = () => {\n    setTab('all');\n    setKind('all');\n    setQuery('');\n    setSort('default');\n  };\n\n  const tabs: { key: Tab; label: string }[] = [\n    { key: 'all', label: t.tabAll },\n    { key: 'seva', label: t.tabSeva },\n    { key: 'corpus', label: t.tabCorpus },\n  ];\n\n  return (\n    <div id=\"seva-list\" className=\"scroll-mt-24\">\n      {/* Tabs */}\n      <div role=\"group\" aria-label={t.tabsLabel} className=\"flex flex-wrap gap-3\">\n        {tabs.map((x) => {\n          const on = tab === x.key;\n          return (\n            <button\n              key={x.key}\n              type=\"button\"\n              aria-pressed={on}\n              onClick={() => setTab(x.key)}\n              className={`rounded-md border px-5 py-2 text-sm font-bold transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron ${\n                on ? 'border-maroon bg-maroon text-white' : 'border-maroon/30 bg-white text-maroon hover:bg-rose'\n              }`}\n            >\n              {x.label} <span className={on ? 'text-rose' : 'text-charcoal/60'}>({counts[x.key]})</span>\n            </button>\n          );\n        })}\n      </div>\n\n      <div className=\"mt-8 grid items-start gap-8 lg:grid-cols-[minmax(0,1fr)_400px]\">\n        {/* Catalogue */}\n        <div>\n          <h2 className=\"font-display text-3xl font-semibold text-maroon sm:text-4xl [html[lang='ta']_&]:!leading-[1.3] [html[lang='ta']_&]:text-2xl [html[lang='ta']_&]:sm:text-3xl\">\n            {tab === 'corpus' ? t.catalogTitleCorpus : t.catalogTitle}\n          </h2>\n\n          <div className=\"mt-5 grid gap-3 sm:grid-cols-[1fr_200px]\">\n            <label className=\"block\">\n              <span className=\"sr-only\">{t.searchLabel}</span>\n              <input\n                type=\"search\"\n                value={query}\n                onChange={(e) => setQuery(e.target.value)}\n                placeholder={t.searchPlaceholder}\n                className=\"w-full rounded-md border border-rose bg-white px-4 py-2.5 text-charcoal placeholder:text-charcoal/50 focus:border-saffron focus:outline-none focus-visible:ring-2 focus-visible:ring-saffron/40\"\n              />\n            </label>\n            <label className=\"block\">\n              <span className=\"sr-only\">{t.sortLabel}</span>\n              <select\n                value={sort}\n                onChange={(e) => setSort(e.target.value)}\n                className=\"w-full rounded-md border border-rose bg-white px-3 py-2.5 text-charcoal focus:border-saffron focus:outline-none focus-visible:ring-2 focus-visible:ring-saffron/40\"\n              >\n                {t.sortOptions.map((o) => (\n                  <option key={o.key} value={o.key}>{o.label}</option>\n                ))}\n              </select>\n            </label>\n          </div>\n\n          {/* Kinds inside the Seva List */}\n          {tab !== 'corpus' && (\n            <div role=\"group\" aria-label={t.filterLabel} className=\"mt-4 flex flex-wrap gap-2\">\n              {t.filters.map((f) => {\n                const on = kind === f.key;\n                return (\n                  <button\n                    key={f.key}\n                    type=\"button\"\n                    aria-pressed={on}\n                    onClick={() => setKind(f.key)}\n                    className={`rounded-full px-4 py-1.5 text-sm font-semibold ring-1 transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron ${\n                      on ? 'bg-saffron text-charcoal ring-saffron' : 'bg-white text-maroon ring-saffron/60 hover:bg-rose'\n                    }`}\n                  >\n                    {f.label}\n                  </button>\n                );\n              })}\n            </div>\n          )}\n\n          <p role=\"status\" className=\"mt-4 text-sm font-semibold text-charcoal/70\">{t.countLabel.replace('{n}', String(shown.length))}</p>\n\n          {shown.length > 0 ? (\n            <ul className=\"mt-4 grid gap-4 sm:grid-cols-2\">\n              {shown.map((s) => (\n                <li key={s.slug} className=\"h-full\">\n                  <SevaOfferCard\n                    seva={s}\n                    locale={locale}\n                    t={t}\n                    selected={selected?.slug === s.slug}\n                    closed={isClosed(s)}\n                    past={isPast(s)}\n                    onSelect={() => pick(s)}\n                  />\n                </li>\n              ))}\n            </ul>\n          ) : (\n            <div className=\"mt-6 rounded-2xl bg-rose/50 px-6 py-12 text-center\">\n              <p className=\"font-serif text-lg text-charcoal\">{t.noResults}</p>\n              <button type=\"button\" onClick={reset} className=\"mt-4 rounded-md bg-maroon px-5 py-2.5 font-semibold text-white hover:bg-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\">\n                {t.clearFilters}\n              </button>\n            </div>\n          )}\n        </div>\n\n        {/* Booking panel */}\n        <div ref={panelRef} className=\"scroll-mt-24 p-1 lg:sticky lg:top-24 lg:max-h-[calc(100vh-7rem)] lg:overflow-y-auto\">\n          <SankalpamWizard seva={selected} locale={locale} t={t} onChangeSeva={() => setSelected(null)} />\n        </div>\n      </div>\n    </div>\n  );\n}\n","src/app/[locale]/sevas/page.tsx":"import type { Metadata } from 'next';\nimport Link from 'next/link';\nimport { notFound } from 'next/navigation';\nimport SevaList from '@/components/SevaList';\nimport { getDictionary } from '@/lib/dictionary';\nimport { isLocale } from '@/lib/i18n';\n\ntype Params = { params: Promise<{ locale: string }> };\n\nexport async function generateMetadata({ params }: Params): Promise<Metadata> {\n  const { locale } = await params;\n  if (!isLocale(locale)) return {};\n  const t = getDictionary(locale);\n  return {\n    title: `${t.sevas.meta.title} | ${t.site.name}`,\n    description: t.sevas.meta.description,\n  };\n}\n\nfunction Flame({ className = '' }: { className?: string }) {\n  return (\n    <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"currentColor\" aria-hidden=\"true\" className={`shrink-0 ${className}`}>\n      <path d=\"M12 2c.6 3.2 4.5 5.4 4.5 10a4.5 4.5 0 0 1-9 0c0-2 .9-3.2 1.8-4.4.4 1.2 1 1.8 1.7 2C11.3 7.7 11.6 5 12 2z\" />\n    </svg>\n  );\n}\n\nfunction Arrow() {\n  return (\n    <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2.5\" strokeLinecap=\"round\" strokeLinejoin=\"round\" aria-hidden=\"true\" className=\"transition-transform duration-300 group-hover:translate-x-1.5\">\n      <path d=\"M5 12h14M13 6l6 6-6 6\" />\n    </svg>\n  );\n}\n\nfunction Mandala({ className = '' }: { className?: string }) {\n  return (\n    <svg aria-hidden=\"true\" viewBox=\"0 0 200 200\" className={className} fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.2\">\n      {[0, 30, 60, 90, 120, 150].map((d) => (\n        <ellipse key={d} cx=\"100\" cy=\"100\" rx=\"22\" ry=\"80\" transform={`rotate(${d} 100 100)`} />\n      ))}\n      <circle cx=\"100\" cy=\"100\" r=\"80\" />\n      <circle cx=\"100\" cy=\"100\" r=\"30\" />\n    </svg>\n  );\n}\n\nexport default async function SevasPage({ params }: Params) {\n  const { locale } = await params;\n  if (!isLocale(locale)) notFound();\n  const dict = getDictionary(locale);\n  const t = dict.sevas;\n  const href = (p: string) => `/${locale}${p}`;\n\n  return (\n    <main>\n      {/* 1. Hero */}\n      <section aria-labelledby=\"sevas-title\" className=\"relative isolate overflow-hidden bg-gradient-to-b from-rose/80 via-white to-white\">\n        <Mandala className=\"absolute -right-40 -top-40 -z-10 h-[36rem] w-[36rem] text-maroon/[0.06]\" />\n        <Mandala className=\"absolute -bottom-52 -left-40 -z-10 h-[30rem] w-[30rem] text-saffron/[0.12]\" />\n\n        <nav aria-label={t.crumbLabel} className=\"mx-auto max-w-6xl px-4 pt-6 text-sm text-charcoal/80 lg:px-8\">\n          <ol className=\"flex flex-wrap items-center gap-2\">\n            <li><Link href={href('')} className=\"underline-offset-4 hover:text-maroon hover:underline\">{dict.nav.home}</Link></li>\n            <li aria-hidden=\"true\">/</li>\n            <li aria-current=\"page\" className=\"font-semibold text-maroon\">{dict.nav.seva}</li>\n          </ol>\n        </nav>\n\n        <div className=\"mx-auto max-w-3xl px-4 pb-14 pt-10 text-center sm:pb-16\">\n          <p className=\"inline-flex items-center gap-2 rounded-full border border-saffron bg-white px-4 py-1.5 text-sm font-semibold text-maroon sm:text-base\">\n            <Flame className=\"text-saffron\" />\n            <span>{t.eyebrow}</span>\n          </p>\n          <h1 id=\"sevas-title\" className=\"animate-fade-up mt-5 font-display text-5xl font-semibold leading-[1.1] text-maroon motion-reduce:animate-none sm:text-6xl [html[lang='ta']_&]:!leading-[1.3] [html[lang='ta']_&]:text-4xl [html[lang='ta']_&]:sm:text-5xl\">{t.title}</h1>\n          <div aria-hidden=\"true\" className=\"mt-4 flex items-center justify-center gap-3\">\n            <span className=\"h-px w-14 bg-saffron\" />\n            <span className=\"h-2 w-2 rotate-45 bg-saffron\" />\n            <span className=\"h-px w-14 bg-saffron\" />\n          </div>\n          <p className=\"mx-auto mt-5 max-w-2xl font-serif text-lg leading-relaxed text-charcoal/90 sm:text-xl\">{t.intro}</p>\n\n          <div className=\"mt-8 flex flex-wrap justify-center gap-3\">\n            <a href=\"#seva-list\" className=\"inline-flex items-center rounded-full bg-maroon px-6 py-2.5 font-semibold text-white transition-colors hover:bg-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\">{t.listLabel}</a>\n            <Link href={href('/cart')} className=\"inline-flex items-center rounded-full border-2 border-saffron bg-white px-6 py-2.5 font-semibold text-maroon transition-colors hover:bg-rose focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\">{dict.shop.cartTitle}</Link>\n          </div>\n        </div>\n      </section>\n\n      {/* 2. Seva list */}\n      <section aria-label={t.listLabel} className=\"bg-white pb-16 pt-2 sm:pb-20\">\n        <div className=\"mx-auto max-w-6xl px-4 lg:px-8\">\n          <SevaList t={t} locale={locale} />\n        </div>\n      </section>\n\n      {/* 3. Help */}\n      <section aria-labelledby=\"help-title\" className=\"bg-saffron py-10 text-charcoal sm:py-12\">\n        <div className=\"mx-auto flex max-w-6xl flex-col items-center gap-6 px-4 text-center lg:flex-row lg:justify-between lg:px-8 lg:text-left\">\n          <div className=\"max-w-2xl\">\n            <h2 id=\"help-title\" className=\"font-display text-3xl font-semibold leading-tight !text-charcoal sm:text-4xl\">{t.helpTitle}</h2>\n            <p className=\"mt-2 text-lg\">{t.helpText}</p>\n          </div>\n          <Link\n            href={href('/contact')}\n            className=\"group inline-flex items-center gap-2 rounded-md bg-charcoal px-7 py-3 font-semibold text-white transition-colors hover:bg-maroon focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-charcoal\"\n          >\n            {t.helpCta}\n            <Arrow />\n          </Link>\n        </div>\n      </section>\n    </main>\n  );\n}\n","src/app/[locale]/sevas/[slug]/page.tsx":"import type { Metadata } from 'next';\nimport Link from 'next/link';\nimport { notFound } from 'next/navigation';\nimport SevaCard from '@/components/sevas/SevaCard';\nimport SankalpamWizard from '@/components/sevas/SankalpamWizard';\nimport SectionTitle from '@/components/SectionTitle';\nimport { SEVAS, getSeva, txt } from '@/data/sevas';\nimport { getDictionary } from '@/lib/dictionary';\nimport { rupees, sevaPhoto } from '@/lib/format';\nimport { isLocale, locales } from '@/lib/i18n';\n\ntype Params = { params: Promise<{ locale: string; slug: string }> };\n\nexport const dynamicParams = false;\nexport const generateStaticParams = () => locales.flatMap((locale) => SEVAS.map((s) => ({ locale, slug: s.slug })));\n\nexport async function generateMetadata({ params }: Params): Promise<Metadata> {\n  const { locale, slug } = await params;\n  const seva = getSeva(slug);\n  if (!isLocale(locale) || !seva) return {};\n  const t = getDictionary(locale);\n  return { title: `${txt(seva.name, locale)} | ${t.site.name}` };\n}\n\nfunction Calendar() {\n  return (\n    <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\" aria-hidden=\"true\" className=\"shrink-0\">\n      <rect x=\"3\" y=\"5\" width=\"18\" height=\"16\" rx=\"2\" />\n      <path d=\"M3 10h18M8 3v4M16 3v4\" />\n    </svg>\n  );\n}\n\nexport default async function SevaDetailPage({ params }: Params) {\n  const { locale, slug } = await params;\n  if (!isLocale(locale)) notFound();\n  const seva = getSeva(slug);\n  if (!seva) notFound();\n\n  const dict = getDictionary(locale);\n  const t = dict.sevas;\n  const name = txt(seva.name, locale);\n  const kindLabel = seva.kind === 'corpus' ? t.tabCorpus : t.filters.find((f) => f.key === seva.kind)?.label ?? '';\n  const paragraphs = seva.description[locale];\n  const related = SEVAS.filter((s) => s.kind === seva.kind && s.slug !== seva.slug).slice(0, 3);\n  const href = (p: string) => `/${locale}${p}`;\n\n  return (\n    <main>\n      <section className=\"bg-gradient-to-b from-rose/80 to-white\">\n        <nav aria-label={t.crumbLabel} className=\"mx-auto max-w-6xl px-4 pb-2 pt-6 text-sm text-charcoal/80 lg:px-8\">\n          <ol className=\"flex flex-wrap items-center gap-2\">\n            <li><Link href={href('')} className=\"underline-offset-4 hover:text-maroon hover:underline\">{dict.nav.home}</Link></li>\n            <li aria-hidden=\"true\">/</li>\n            <li><Link href={href('/sevas')} className=\"underline-offset-4 hover:text-maroon hover:underline\">{dict.nav.seva}</Link></li>\n            <li aria-hidden=\"true\">/</li>\n            <li aria-current=\"page\" className=\"font-semibold text-maroon\">{name}</li>\n          </ol>\n        </nav>\n      </section>\n\n      {/* Photo on the left, details and booking form on the right */}\n      <section className=\"bg-white pb-12 pt-4 sm:pb-16\">\n        <div className=\"mx-auto grid max-w-6xl items-start gap-10 px-4 lg:grid-cols-2 lg:gap-14 lg:px-8\">\n          <div className=\"lg:sticky lg:top-24\">\n            <div className=\"relative pb-4 pr-4\">\n              <div aria-hidden=\"true\" className=\"absolute inset-0 translate-x-4 translate-y-4 rounded-2xl bg-maroon\" />\n              <div role=\"img\" aria-label={name} className=\"relative aspect-[4/3] w-full rounded-2xl bg-maroon bg-cover bg-center shadow-xl ring-4 ring-white\" style={{ backgroundImage: sevaPhoto(seva.slug) }} />\n            </div>\n          </div>\n\n          <div>\n            <p className=\"inline-block rounded-full bg-maroon px-4 py-1 text-xs font-bold uppercase tracking-wider text-white [html[lang='ta']_&]:tracking-normal\">{kindLabel}</p>\n            <h1 className=\"mt-3 font-display text-4xl font-semibold leading-tight text-maroon sm:text-5xl [html[lang='ta']_&]:!leading-[1.3] [html[lang='ta']_&]:text-3xl [html[lang='ta']_&]:sm:text-4xl\">{name}</h1>\n\n            {seva.benefit && <p className=\"mt-3 font-serif text-lg text-charcoal/90\"><span className=\"font-semibold\">{t.benefitsLabel}</span> {txt(seva.benefit, locale)}</p>}\n\n            <dl className=\"mt-5 grid gap-4 rounded-xl bg-rose/50 p-5 sm:grid-cols-2\">\n              <div>\n                <dt className=\"text-xs font-bold uppercase tracking-wider text-maroon [html[lang='ta']_&]:tracking-normal\">{t.amountLabel}</dt>\n                <dd className=\"mt-1 font-display text-3xl font-semibold text-charcoal\">\n                  {seva.amount > 0 ? rupees(seva.amount) : <span className=\"text-2xl text-saffron [html[lang='ta']_&]:text-xl\">{t.abilityLabel}</span>}\n                </dd>\n              </div>\n              <div>\n                <dt className=\"text-xs font-bold uppercase tracking-wider text-maroon [html[lang='ta']_&]:tracking-normal\">{t.whenLabel}</dt>\n                <dd className=\"mt-1 flex items-center gap-2 text-lg font-semibold text-charcoal\"><Calendar />{txt(seva.when, locale)}</dd>\n              </div>\n            </dl>\n\n            <div className=\"mt-6\">\n              <SankalpamWizard seva={seva} locale={locale} t={t} fixed />\n            </div>\n          </div>\n        </div>\n      </section>\n\n      {/* About */}\n      <section aria-labelledby=\"about-title\" className=\"bg-rose/50 py-12 sm:py-16\">\n        <div className=\"mx-auto max-w-4xl px-4 lg:px-8\">\n          <h2 id=\"about-title\" className=\"font-display text-3xl font-semibold text-maroon sm:text-4xl [html[lang='ta']_&]:!leading-[1.3]\">{t.aboutTitle}</h2>\n          <div aria-hidden=\"true\" className=\"mt-3 flex items-center gap-3\"><span className=\"h-px w-12 bg-saffron\" /><span className=\"h-2 w-2 rotate-45 bg-saffron\" /><span className=\"h-px w-12 bg-saffron\" /></div>\n          {paragraphs.length > 0 ? (\n            paragraphs.map((p) => <p key={p} className=\"mt-5 font-serif text-lg leading-relaxed text-charcoal\">{p}</p>)\n          ) : (\n            <p className=\"mt-5 font-serif text-lg leading-relaxed text-charcoal/80\">{t.descriptionEmpty}</p>\n          )}\n\n          {seva.includes.length > 0 && (\n            <div className=\"mt-10\">\n              <h3 className=\"font-display text-2xl font-semibold text-maroon\">{t.includesTitle}</h3>\n              <ul className=\"mt-4 divide-y divide-rose overflow-hidden rounded-xl bg-white ring-1 ring-rose\">\n                {seva.includes.map((i) => (\n                  <li key={i.label.en} className=\"flex items-start justify-between gap-4 px-5 py-3\">\n                    <span className=\"text-charcoal\">{txt(i.label, locale)}</span>\n                    <span className=\"shrink-0 font-bold text-charcoal\">{rupees(i.price)}</span>\n                  </li>\n                ))}\n              </ul>\n            </div>\n          )}\n        </div>\n      </section>\n\n      {/* How to book */}\n      <section aria-labelledby=\"how-title\" className=\"bg-white py-12 sm:py-16\">\n        <div className=\"mx-auto max-w-6xl px-4 lg:px-8\">\n          <SectionTitle id=\"how-title\" title={t.howTitle} />\n          <ol className=\"mt-10 grid gap-6 sm:grid-cols-2 lg:grid-cols-4\">\n            {t.howSteps.map((s, i) => (\n              <li key={s.title} className=\"rounded-2xl border-t-4 border-saffron bg-rose/40 p-6 text-center\">\n                <span aria-hidden=\"true\" className=\"mx-auto flex h-12 w-12 items-center justify-center rounded-full bg-maroon font-display text-2xl font-semibold text-white\">{i + 1}</span>\n                <h3 className=\"mt-3 font-display text-xl font-semibold text-maroon [html[lang='ta']_&]:!leading-[1.4]\">{s.title}</h3>\n                <p className=\"mt-1 text-charcoal/85\">{s.text}</p>\n              </li>\n            ))}\n          </ol>\n        </div>\n      </section>\n\n      {/* Related sevas */}\n      {related.length > 0 && (\n        <section aria-labelledby=\"related-title\" className=\"bg-rose/50 py-12 sm:py-16\">\n          <div className=\"mx-auto max-w-6xl px-4 lg:px-8\">\n            <SectionTitle id=\"related-title\" title={t.relatedTitle} />\n            <ul className=\"mt-10 grid gap-6 sm:grid-cols-2 lg:grid-cols-3\">\n              {related.map((s) => (\n                <li key={s.slug} className=\"h-full\"><SevaCard seva={s} locale={locale} t={t} /></li>\n              ))}\n            </ul>\n            <p className=\"mt-8 text-center\">\n              <Link href={href('/sevas')} className=\"font-bold text-maroon underline underline-offset-4\">{t.backLabel}</Link>\n            </p>\n          </div>\n        </section>\n      )}\n    </main>\n  );\n}\n","src/components/cart/CartProvider.tsx":"'use client';\n\n// The cart lives in the browser (localStorage) while the site is UI-only.\n// When the backend is ready, replace the read/write calls below with API calls.\n\nimport type { FamilyMember } from '@/data/sankalpam';\nimport { createContext, useCallback, useContext, useEffect, useMemo, useState, type ReactNode } from 'react';\n\nexport type CartLine = {\n  id: string;\n  slug: string;\n  qty: number;\n  unit: number;       // amount for one, in rupees\n  date: string;       // YYYY-MM-DD\n  devotee: string;\n  gotram: string;\n  nakshatram: string;\n  rasi?: string;                 // moon sign (optional, added with the sankalpam form)\n  family?: FamilyMember[];       // family members named in the sankalpam\n};\n\nexport type Contact = { name: string; phone: string; email: string; address: string; city: string; state: string; pin: string; country: string };\nexport const EMPTY_CONTACT: Contact = { name: '', phone: '', email: '', address: '', city: '', state: '', pin: '', country: 'India' };\n\nexport type Order = { id: string; placedAt: string; lines: CartLine[]; total: number; contact: Contact; method: string };\n\nconst KEY_CART = 'vedaneri.cart.v1';\nconst KEY_CONTACT = 'vedaneri.contact.v1';\nconst KEY_ORDER = 'vedaneri.order.v1';\n\n// Browser storage can be blocked or empty (private windows), so every call is wrapped.\nfunction read<T>(key: string, fallback: T): T {\n  try {\n    const raw = window.localStorage.getItem(key);\n    return raw ? (JSON.parse(raw) as T) : fallback;\n  } catch {\n    return fallback;\n  }\n}\nfunction write(key: string, value: unknown) {\n  try {\n    window.localStorage.setItem(key, JSON.stringify(value));\n  } catch {\n    /* ignore */\n  }\n}\n\ntype CartContextValue = {\n  ready: boolean;                 // false until the saved cart has been read\n  lines: CartLine[];\n  count: number;                  // number of sevas (quantities added up)\n  total: number;\n  add: (line: Omit<CartLine, 'id'>) => void;\n  setQty: (id: string, qty: number) => void;\n  remove: (id: string) => void;\n  contact: Contact;\n  saveContact: (c: Contact) => void;\n  order: Order | null;            // the last paid order\n  placeOrder: (method: string) => Order | null;\n};\n\nconst CartContext = createContext<CartContextValue | null>(null);\n\nexport function useCart() {\n  const ctx = useContext(CartContext);\n  if (!ctx) throw new Error('useCart must be used inside <CartProvider>');\n  return ctx;\n}\n\nexport default function CartProvider({ children }: { children: ReactNode }) {\n  const [ready, setReady] = useState(false);\n  const [lines, setLines] = useState<CartLine[]>([]);\n  const [contact, setContact] = useState<Contact>(EMPTY_CONTACT);\n  const [order, setOrder] = useState<Order | null>(null);\n\n  useEffect(() => {\n    setLines(read<CartLine[]>(KEY_CART, []));\n    setContact({ ...EMPTY_CONTACT, ...read<Partial<Contact>>(KEY_CONTACT, {}) });\n    setOrder(read<Order | null>(KEY_ORDER, null));\n    setReady(true);\n  }, []);\n\n  useEffect(() => {\n    if (!ready) return;\n    write(KEY_CART, lines);\n    write(KEY_CONTACT, contact);\n    write(KEY_ORDER, order);\n  }, [ready, lines, contact, order]);\n\n  const add = useCallback((line: Omit<CartLine, 'id'>) => {\n    const id = `${line.slug}-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;\n    setLines((l) => [...l, { ...line, id }]);\n  }, []);\n\n  const setQty = useCallback((id: string, qty: number) => {\n    setLines((l) => l.map((x) => (x.id === id ? { ...x, qty } : x)));\n  }, []);\n\n  const remove = useCallback((id: string) => setLines((l) => l.filter((x) => x.id !== id)), []);\n\n  const saveContact = useCallback((c: Contact) => setContact(c), []);\n\n  const total = useMemo(() => lines.reduce((s, l) => s + l.unit * l.qty, 0), [lines]);\n  const count = useMemo(() => lines.reduce((s, l) => s + l.qty, 0), [lines]);\n\n  const placeOrder = useCallback(\n    (method: string) => {\n      if (lines.length === 0) return null;\n      const d = new Date();\n      const stamp = `${d.getFullYear()}${String(d.getMonth() + 1).padStart(2, '0')}${String(d.getDate()).padStart(2, '0')}`;\n      const o: Order = {\n        id: `VN-${stamp}-${Math.floor(1000 + Math.random() * 9000)}`,\n        placedAt: d.toISOString(),\n        lines,\n        total,\n        contact,\n        method,\n      };\n      setOrder(o);\n      setLines([]);\n      return o;\n    },\n    [lines, total, contact],\n  );\n\n  const value = useMemo<CartContextValue>(\n    () => ({ ready, lines, count, total, add, setQty, remove, contact, saveContact, order, placeOrder }),\n    [ready, lines, count, total, add, setQty, remove, contact, saveContact, order, placeOrder],\n  );\n\n  return <CartContext.Provider value={value}>{children}</CartContext.Provider>;\n}\n","src/components/cart/CartView.tsx":"'use client';\n\nimport Link from 'next/link';\nimport type { Dictionary } from '@/lib/dictionary';\nimport type { Locale } from '@/lib/i18n';\nimport { formatDate, rupees, sevaPhoto } from '@/lib/format';\nimport { getSeva, txt } from '@/data/sevas';\nimport { GOTRAMS, NAKSHATRAMS, RASIS, RELATIONS, labelFor } from '@/data/sankalpam';\nimport { useCart } from './CartProvider';\n\nexport default function CartView({ t, locale }: { t: Dictionary['shop']; locale: Locale }) {\n  const { ready, lines, count, total, setQty, remove } = useCart();\n  const href = (p: string) => `/${locale}${p}`;\n\n  if (!ready) return <p role=\"status\" className=\"py-16 text-center text-charcoal/70\">{t.loading}</p>;\n\n  if (lines.length === 0) {\n    return (\n      <div className=\"mx-auto max-w-xl rounded-2xl bg-rose/50 px-6 py-14 text-center\">\n        <p className=\"font-display text-3xl font-semibold text-maroon\">{t.cartEmpty}</p>\n        <p className=\"mt-2 font-serif text-lg text-charcoal/90\">{t.cartEmptyText}</p>\n        <Link href={href('/sevas')} className=\"mt-6 inline-block rounded-md bg-maroon px-7 py-3 font-semibold text-white hover:bg-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\">{t.browse}</Link>\n      </div>\n    );\n  }\n\n  return (\n    <div className=\"grid items-start gap-8 lg:grid-cols-[1fr_360px]\">\n      <ul className=\"space-y-4\">\n        {lines.map((l) => {\n          const seva = getSeva(l.slug);\n          const name = seva ? txt(seva.name, locale) : l.slug;\n          const fixedPrice = seva ? seva.amount > 0 : false;\n          const max = seva?.maxQty ?? 10;\n          return (\n            <li key={l.id} className=\"flex flex-col gap-4 rounded-2xl bg-white p-4 shadow-md ring-1 ring-rose sm:flex-row sm:p-5\">\n              <div role=\"img\" aria-label={name} className=\"h-32 w-full shrink-0 rounded-xl bg-maroon bg-cover bg-center sm:h-28 sm:w-36\" style={{ backgroundImage: sevaPhoto(l.slug) }} />\n              <div className=\"flex min-w-0 flex-1 flex-col\">\n                <h2 className=\"font-display text-2xl font-semibold leading-tight text-maroon [html[lang='ta']_&]:!leading-[1.4] [html[lang='ta']_&]:text-xl\">\n                  <Link href={href(`/sevas/${l.slug}`)} className=\"hover:underline\">{name}</Link>\n                </h2>\n                <dl className=\"mt-2 grid gap-x-6 gap-y-1 text-sm sm:grid-cols-2\">\n                  <div className=\"flex gap-2\"><dt className=\"font-bold text-charcoal/70\">{t.dateLabel}:</dt><dd>{formatDate(l.date, locale)}</dd></div>\n                  <div className=\"flex gap-2\"><dt className=\"font-bold text-charcoal/70\">{t.devoteeLabel}:</dt><dd>{l.devotee}</dd></div>\n                  {l.gotram && <div className=\"flex gap-2\"><dt className=\"font-bold text-charcoal/70\">{t.gotramLabel}:</dt><dd>{labelFor(GOTRAMS, l.gotram, locale)}</dd></div>}\n                  {l.rasi && <div className=\"flex gap-2\"><dt className=\"font-bold text-charcoal/70\">{t.rasiLabel}:</dt><dd>{labelFor(RASIS, l.rasi, locale)}</dd></div>}\n                  {l.nakshatram && <div className=\"flex gap-2\"><dt className=\"font-bold text-charcoal/70\">{t.nakshatramLabel}:</dt><dd>{labelFor(NAKSHATRAMS, l.nakshatram, locale)}</dd></div>}\n                  {l.family && l.family.length > 0 && (\n                    <div className=\"flex gap-2 sm:col-span-2\"><dt className=\"font-bold text-charcoal/70\">{t.familyLabel}:</dt><dd>{l.family.map((m) => (m.relation ? `${m.name} (${labelFor(RELATIONS, m.relation, locale)})` : m.name)).join(', ')}</dd></div>\n                  )}\n                </dl>\n\n                <div className=\"mt-4 flex flex-wrap items-center justify-between gap-3\">\n                  {fixedPrice ? (\n                    <div className=\"inline-flex items-center rounded-md border-2 border-rose\" role=\"group\" aria-label={t.qtyLabel}>\n                      <button type=\"button\" aria-label={t.decrease} disabled={l.qty <= 1} onClick={() => setQty(l.id, l.qty - 1)} className=\"h-10 w-10 text-xl font-bold text-maroon hover:bg-rose disabled:opacity-40\">−</button>\n                      <span aria-live=\"polite\" className=\"w-10 text-center font-bold\">{l.qty}</span>\n                      <button type=\"button\" aria-label={t.increase} disabled={l.qty >= max} onClick={() => setQty(l.id, l.qty + 1)} className=\"h-10 w-10 text-xl font-bold text-maroon hover:bg-rose disabled:opacity-40\">+</button>\n                    </div>\n                  ) : (\n                    <span className=\"text-sm text-charcoal/70\">{t.yourAmount}</span>\n                  )}\n                  <p className=\"font-display text-3xl font-semibold text-charcoal\">{rupees(l.qty * l.unit)}</p>\n                </div>\n                <button type=\"button\" onClick={() => remove(l.id)} className=\"mt-3 self-start text-sm font-semibold text-maroon underline underline-offset-4 hover:text-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-saffron\">{t.remove}</button>\n              </div>\n            </li>\n          );\n        })}\n      </ul>\n\n      <aside aria-label={t.summaryTitle} className=\"rounded-2xl bg-white p-6 shadow-lg ring-2 ring-rose lg:sticky lg:top-24\">\n        <h2 className=\"font-display text-2xl font-semibold text-maroon [html[lang='ta']_&]:!leading-[1.4]\">{t.summaryTitle}</h2>\n        <dl className=\"mt-4 space-y-2\">\n          <div className=\"flex justify-between\"><dt className=\"text-charcoal/80\">{t.itemsLabel}</dt><dd className=\"font-semibold\">{count}</dd></div>\n          <div className=\"flex items-baseline justify-between border-t-2 border-rose pt-4\">\n            <dt className=\"font-bold\">{t.total}</dt>\n            <dd className=\"font-display text-3xl font-semibold text-maroon\">{rupees(total)}</dd>\n          </div>\n        </dl>\n        <Link href={href('/checkout')} className=\"mt-6 block rounded-md bg-maroon px-5 py-3 text-center font-semibold text-white transition-colors hover:bg-charcoal focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-saffron\">{t.checkoutCta}</Link>\n        <Link href={href('/sevas')} className=\"mt-3 block text-center text-sm font-semibold text-maroon underline underline-offset-4\">{t.continueShopping}</Link>\n        <p className=\"mt-4 text-center text-xs text-charcoal/70\">{t.receiptNote}</p>\n      </aside>\n    </div>\n  );\n}\n","src/components/cart/ConfirmationView.tsx":"'use client';\n\nimport Link from 'next/link';\nimport type { Dictionary } from '@/lib/dictionary';\nimport type { Locale } from '@/lib/i18n';\nimport { formatDate, rupees } from '@/lib/format';\nimport { getSeva, txt } from '@/data/sevas';\nimport { GOTRAMS, NAKSHATRAMS, RASIS, RELATIONS, labelFor } from '@/data/sankalpam';\nimport { useCart } from './CartProvider';\n\nexport default function ConfirmationView({ t, locale }: { t: Dictionary['shop']; locale: Locale }) {\n  const { ready, order } = useCart();\n  const href = (p: string) => `/${locale}${p}`;\n\n  if (!ready) return <p role=\"status\" className=\"py-16 text-center text-charcoal/70\">{t.loading}</p>;\n\n  if (!order) {\n    return (\n      <div className=\"mx-auto max-w-xl rounded-2xl bg-rose/50 px-6 py-14 text-center\">\n        <p className=\"font-serif text-lg text-charcoal\">{t.noOrder}</p>\n        <Link href={href('/sevas')} className=\"mt-6 inline-block rounded-md bg-maroon px-7 py-3 font-semibold text-white hover:bg-charcoal\">{t.browse}</Link>\n      </div>\n    );\n  }\n\n  const method = t.methods.find((m) => m.key === order.method)?.label ?? order.method;\n  const placed = order.placedAt.slice(0, 10);\n\n  return (\n    <div className=\"mx-auto max-w-3xl\">\n      <div className=\"rounded-2xl bg-white p-6 shadow-lg ring-2 ring-saffron sm:p-10\">\n        <div className=\"text-center\">\n          <span aria-hidden=\"true\" className=\"mx-auto flex h-16 w-16 items-center justify-center rounded-full bg-saffron text-3xl font-bold text-charcoal\">✓</span>\n          <h2 className=\"mt-4 font-display text-4xl font-semibold text-maroon [html[lang='ta']_&]:!leading-[1.3] [html[lang='ta']_&]:text-3xl\">{t.confirmTitle}</h2>\n          <p className=\"mx-auto mt-2 max-w-xl font-serif text-lg text-charcoal/90\">{t.confirmText}</p>\n          <p className=\"mt-2 text-sm font-semibold text-charcoal/70\">{t.receiptSent.replace('{email}', order.contact.email)}</p>\n        </div>\n\n        <dl className=\"mt-8 grid gap-4 rounded-xl bg-rose/50 p-5 sm:grid-cols-3\">\n          <div><dt className=\"text-xs font-bold uppercase tracking-wider text-maroon [html[lang='ta']_&]:tracking-normal\">{t.orderId}</dt><dd className=\"mt-1 font-bold text-charcoal\">{order.id}</dd></div>\n          <div><dt className=\"text-xs font-bold uppercase tracking-wider text-maroon [html[lang='ta']_&]:tracking-normal\">{t.orderDate}</dt><dd className=\"mt-1 font-bold text-charcoal\">{formatDate(placed, locale)}</dd></div>\n          <div><dt className=\"text-xs font-bold uppercase tracking-wider text-maroon [html[lang='ta']_&]:tracking-normal\">{t.paidWith}</dt><dd className=\"mt-1 font-bold text-charcoal\">{method}</dd></div>\n        </dl>\n\n        <h3 className=\"mt-8 font-display text-2xl font-semibold text-maroon\">{t.yourSevas}</h3>\n        <ul className=\"mt-2 divide-y divide-rose\">\n          {order.lines.map((l) => {\n            const seva = getSeva(l.slug);\n            return (\n              <li key={l.id} className=\"flex items-start justify-between gap-4 py-3\">\n                <div>\n                  <p className=\"font-semibold text-charcoal\">{seva ? txt(seva.name, locale) : l.slug}</p>\n                  <p className=\"text-sm text-charcoal/70\">{formatDate(l.date, locale)} · {l.devotee}{l.gotram ? ` · ${labelFor(GOTRAMS, l.gotram, locale)}` : ''}{l.rasi ? ` · ${labelFor(RASIS, l.rasi, locale)}` : ''}{l.nakshatram ? ` · ${labelFor(NAKSHATRAMS, l.nakshatram, locale)}` : ''}</p>\n                  {l.family && l.family.length > 0 && (\n                    <p className=\"text-sm text-charcoal/70\">{t.familyLabel}: {l.family.map((m) => (m.relation ? `${m.name} (${labelFor(RELATIONS, m.relation, locale)})` : m.name)).join(', ')}</p>\n                  )}\n                  <p className=\"text-sm text-charcoal/70\">{l.qty} × {rupees(l.unit)}</p>\n                </div>\n                <p className=\"shrink-0 font-bold\">{rupees(l.qty * l.unit)}</p>\n              </li>\n            );\n          })}\n        </ul>\n        <p className=\"mt-2 flex items-baseline justify-between border-t-2 border-rose pt-4\">\n          <span className=\"font-bold\">{t.total}</span>\n          <span className=\"font-display text-3xl font-semibold text-maroon\">{rupees(order.total)}</span>\n        </p>\n\n        <div className=\"mt-8 flex flex-col gap-3 sm:flex-row sm:justify-center\">\n          <Link href={href('/sevas')} className=\"rounded-md bg-maroon px-7 py-3 text-center font-semibold text-white hover:bg-charcoal\">{t.moreSevas}</Link>\n          <Link href={href('')} className=\"rounded-md border-2 border-maroon px-7 py-3 text-center font-semibold text-maroon hover:bg-rose\">{t.backHome}</Link>\n        </div>\n      </div>\n    </div>\n  );\n}\n"};
const DICT = {"en":{"sevas":{"tabsLabel":"Seva sections","tabAll":"All Sevas","tabSeva":"Seva List","tabCorpus":"Corpus List","catalogTitle":"Available Sevas & Offerings","catalogTitleCorpus":"Corpus Fund Offerings","abilityShort":"Your choice","benefitsLabel":"Benefits:","addToSevaCart":"Add to Seva Cart","selected":"Selected","pastLabel":"Date passed","stepsLabel":"Booking steps","stepSeva":"Select seva","stepCredentials":"Sankalpam credentials","stepDate":"Date selection","panelTitleSeva":"Choose a seva","panelTextSeva":"Select a seva from the list to begin your booking.","panelEmpty":"Pick a seva with “Add to Seva Cart” and your booking will open here.","panelTitleCred":"Sankalpam Credentials","panelTextCred":"Vedic astrological credentials for sacred chants.","panelTitleDate":"Date Selection","panelTextDate":"Choose when the seva is offered.","kartha":"Kartha name (primary devotee)","gotramFull":"Gotram (Vedic lineage)","rasiFull":"Rasi (Moon sign)","nakshatramFull":"Nakshatram (Birth star)","choose":"Select","otherOption":"Other (type manually)","typeManually":"Type here","optionalNote":"Gotram, rasi and nakshatram are optional. If yours is not in the list, choose “Other” and type it.","addFamily":"Add family member","familyTitle":"Family member {n}","memberName":"Name","relation":"Relation","removeMember":"Remove this member","maxFamily":"You can add up to {n} family members.","familyHelp":"Family members are included in the same sankalpam, under the gotram above.","errMember":"Please enter the family member's name.","back":"Back","nextDate":"Next: Date Selection","changeSeva":"Change","addAndGo":"Add and go to cart","chooseAnother":"Choose another seva","decrease":"Decrease quantity","increase":"Increase quantity"},"shop":{"rasiLabel":"Rasi","familyLabel":"Family members"}},"ta":{"sevas":{"tabsLabel":"சேவைப் பிரிவுகள்","tabAll":"அனைத்து சேவைகள்","tabSeva":"சேவா பட்டியல்","tabCorpus":"கார்பஸ் பட்டியல்","catalogTitle":"கிடைக்கும் சேவைகளும் காணிக்கைகளும்","catalogTitleCorpus":"கார்பஸ் நிதி காணிக்கைகள்","abilityShort":"உங்கள் விருப்பம்","benefitsLabel":"பலன்கள்:","addToSevaCart":"சேவைக் கூடையில் சேர்","selected":"தேர்ந்தெடுக்கப்பட்டது","pastLabel":"தேதி கடந்துவிட்டது","stepsLabel":"முன்பதிவுப் படிகள்","stepSeva":"சேவையைத் தேர்ந்தெடுக்க","stepCredentials":"சங்கல்ப விவரங்கள்","stepDate":"தேதி தேர்வு","panelTitleSeva":"ஒரு சேவையைத் தேர்ந்தெடுங்கள்","panelTextSeva":"முன்பதிவைத் தொடங்க பட்டியலில் ஒரு சேவையைத் தேர்ந்தெடுக்கவும்.","panelEmpty":"“சேவைக் கூடையில் சேர்” மூலம் ஒரு சேவையைத் தேர்ந்தெடுத்தால் உங்கள் முன்பதிவு இங்கே திறக்கும்.","panelTitleCred":"சங்கல்ப விவரங்கள்","panelTextCred":"புனித மந்திரங்களுக்கான வேத ஜோதிட விவரங்கள்.","panelTitleDate":"தேதி தேர்வு","panelTextDate":"சேவை நடைபெற வேண்டிய நாளைத் தேர்ந்தெடுக்கவும்.","kartha":"கர்த்தா பெயர் (முதன்மை பக்தர்)","gotramFull":"கோத்திரம் (வேத வம்சம்)","rasiFull":"ராசி (சந்திர ராசி)","nakshatramFull":"நட்சத்திரம் (பிறந்த நட்சத்திரம்)","choose":"தேர்ந்தெடுக்கவும்","otherOption":"மற்றவை (கைமுறையாக உள்ளிட)","typeManually":"இங்கே தட்டச்சு செய்யவும்","optionalNote":"கோத்திரம், ராசி, நட்சத்திரம் விருப்பத்துக்குரியவை. உங்களுடையது பட்டியலில் இல்லையெனில் “மற்றவை” என்பதைத் தேர்ந்து தட்டச்சு செய்யவும்.","addFamily":"குடும்ப உறுப்பினரைச் சேர்","familyTitle":"குடும்ப உறுப்பினர் {n}","memberName":"பெயர்","relation":"உறவு","removeMember":"இந்த உறுப்பினரை நீக்கு","maxFamily":"அதிகபட்சம் {n} குடும்ப உறுப்பினர்களைச் சேர்க்கலாம்.","familyHelp":"குடும்ப உறுப்பினர்கள் மேலே உள்ள கோத்திரத்தின் கீழ் அதே சங்கல்பத்தில் சேர்க்கப்படுவர்.","errMember":"குடும்ப உறுப்பினரின் பெயரை உள்ளிடவும்.","back":"பின்செல்ல","nextDate":"அடுத்து: தேதி தேர்வு","changeSeva":"மாற்று","addAndGo":"சேர்த்து கூடைக்குச் செல்ல","chooseAnother":"மற்றொரு சேவையைத் தேர்ந்தெடு","decrease":"எண்ணிக்கையைக் குறை","increase":"எண்ணிக்கையைக் கூட்டு"},"shop":{"rasiLabel":"ராசி","familyLabel":"குடும்ப உறுப்பினர்கள்"}}};
const RETIRE = ['src/components/sevas/SevaPurchase.tsx']; // replaced by SankalpamWizard.tsx; kept as .bak

const backup = (p) => { if (fs.existsSync(p) && !fs.existsSync(p + '.bak')) fs.copyFileSync(p, p + '.bak'); };

let n = 0;
for (const [rel, content] of Object.entries(FILES)) {
  const p = path.join(root, ...rel.split('/'));
  fs.mkdirSync(path.dirname(p), { recursive: true });
  backup(p);
  fs.writeFileSync(p, content, 'utf8');
  console.log('wrote   ' + rel);
  n++;
}

for (const rel of RETIRE) {
  const p = path.join(root, ...rel.split('/'));
  if (fs.existsSync(p)) {
    if (fs.existsSync(p + '.bak')) fs.unlinkSync(p + '.bak');
    fs.renameSync(p, p + '.bak');
    console.log('retired ' + rel + ' (saved as .bak)');
  }
}

for (const l of ['en', 'ta']) {
  const p = path.join(root, 'src', 'dictionaries', l + '.json');
  backup(p);
  const json = JSON.parse(fs.readFileSync(p, 'utf8'));
  if (!json.sevas || !json.shop) { console.error(l + '.json has no sevas/shop block. Run install-seva-shop.mjs first.'); process.exit(1); }
  Object.assign(json.sevas, DICT[l].sevas);
  Object.assign(json.shop, DICT[l].shop);
  fs.writeFileSync(p, JSON.stringify(json, null, 2) + '\n', 'utf8');
  console.log('merged  ' + l + '.json (new sevas and shop keys added)');
}

console.log('\nDone: ' + n + ' files. Now run (inside apps\\web):  npx tsc --noEmit   then restart npm run dev');
